114:   private commitTile(gx: number, gy: number, type: TileType, z: number): void {
115:     // 1. Write to world + redraw chunk synchronously (visible this frame).
116:     this.world.place({ gx, gy, z, type });
117:     const [cx, cy] = TileWorld.chunkOf(gx, gy);
118:     this.chunks.redrawNow(TileWorld.chunkKey(cx, cy));
119: 
120:     // 2. Union-find
121:     const tk = tileKeyFor(gx, gy);
122:     const initialRoot = this.connectivity.add(tk, gx, gy, type);
123:     const consumedRoots: string[] = [];
124: 
125:     for (const [dx, dy] of this.connectivity.NEIGHBORS_8) {
126:       const nk = tileKeyFor(gx + dx, gy + dy);
127:       if (!this.connectivity.has(nk)) continue;
128:       const rootA = this.connectivity.find(initialRoot);
129:       const rootB = this.connectivity.find(nk);
130:       if (rootA === rootB) continue;
131:       const newRoot = this.connectivity.union(rootA, rootB);
132:       const loser = newRoot === rootA ? rootB : rootA;
133:       consumedRoots.push(loser);
134:     }
135: 
136:     // 3. Classify + sync modules
137:     const finalRoot = this.connectivity.find(initialRoot);
138:     const stats = this.connectivity.stats(finalRoot);
139:     this.modules.sync(this.ecs, stats, consumedRoots);
140:   }
