8: 
9:   constructor(private scene: Phaser.Scene, private world: TileWorld) {}
10: 
11:   update(): void {
12:     for (const ck of this.world.consumeDirty()) this.redraw(ck);
13:   }
14: 
15:   /** Synchronous redraw — call from input handlers for zero-latency commits. */
16:   redrawNow(ck: string): void {
17:     const dirty = this.world.consumeDirty();
18:     for (const dirtyChunk of dirty) this.redraw(dirtyChunk);
19:     if (!dirty.includes(ck)) this.redraw(ck);
20:   }
21: 
22:   private redraw(ck: string): void {
23:     const [cxStr, cyStr] = ck.split(',');
24:     const cx = Number(cxStr), cy = Number(cyStr);
25: 
26:     let g = this.gfx.get(ck);
27:     if (!g) {
28:       g = this.scene.add.graphics();
29:       g.setPosition(cx * CHUNK_PX, cy * CHUNK_PX);
30:       g.setDepth(cy * 10000);
31:       this.gfx.set(ck, g);
32:     }
33:     g.clear();
34: 
35:     const tiles: Tile[] = [...this.world.chunkTiles(cx, cy)];
36:     tiles.sort((a, b) => (a.gy - b.gy) || (a.z - b.z));
37:     for (const t of tiles) {
38:       const localX = (t.gx - cx * CHUNK_SIZE) * TILE_PX;
39:       const localY = (t.gy - cy * CHUNK_SIZE) * TILE_PX;
40:       this.drawTile(g, localX, localY, t);
41:     }
42:   }
