47:     const colors = TILE_COLORS[t.type];
48: 
49:     if (t.z > 0) {
50:       g.fillStyle(0x000000, 0.4);
51:       g.fillRect(x + 3, y - zPx + 3, size, size);
52:       g.fillStyle(colors.dark, 1);
53:       g.fillRect(x, y - zPx, size, zPx + size);
54:       g.fillStyle(colors.top, 1);
55:       g.fillRect(x, y - zPx, size, size);
56:       g.lineStyle(1, 0x000000, 0.3);
57:       g.strokeRect(x, y - zPx, size, size);
58:     } else {
59:       g.fillStyle(colors.top, 1);
60:       g.fillRect(x, y, size, size);
