4: /** Priority-ordered classification. Any misfit cluster with ≥3 tiles becomes a wound. */
5: export function classify(stats: ComponentStats): ModuleType | null {
6:   if (stats.tileCount < 3) return null;
7:   const c = (t: TileType) => stats.typeCounts.get(t) ?? 0;
8: 
9:   if (c('glyph') > 0) return 'glyph';
10:   if (c('bloom') >= 2 && c('stem') >= 3) return 'canopy';
11:   if (c('root') >= 4) return 'taproot';
12:   if (c('leaf') >= 3 && c('stem') >= 2) return 'trunk';
13:   return 'wound';
14: }

