25: export class Connectivity {
26:   private parent = new Map<string, string>();
27:   private rank = new Map<string, number>();
28:   private tiles = new Map<string, Set<string>>();
29:   private typeCounts = new Map<string, Map<TileType, number>>();
30:   private centroidSum = new Map<string, { x: number; y: number }>();
31:   private tileCount = new Map<string, number>();
32: 
33:   has(tk: string): boolean { return this.parent.has(tk); }
34: 
35:   find(k: string): string {
36:     let root = k;
37:     while (this.parent.get(root) !== root) {
38:       const next = this.parent.get(root);
39:       if (next === undefined) return root;
40:       root = next;
41:     }
42:     while (this.parent.get(k) !== root) {
43:       const next = this.parent.get(k)!;
44:       this.parent.set(k, root);
45:       k = next;
46:     }
47:     return root;
48:   }
49: 
50:   add(tk: string, gx: number, gy: number, type: TileType): string {
51:     if (this.parent.has(tk)) return this.find(tk);
52:     this.parent.set(tk, tk);
53:     this.rank.set(tk, 0);
54:     this.tiles.set(tk, new Set([tk]));
55:     this.typeCounts.set(tk, new Map([[type, 1]]));
56:     this.centroidSum.set(tk, { x: gx, y: gy });
57:     this.tileCount.set(tk, 1);
58:     return tk;
59:   }
60: 
61:   union(a: string, b: string): string {
62:     const ra = this.find(a), rb = this.find(b);
63:     if (ra === rb) return ra;
64:     const rankA = this.rank.get(ra) ?? 0, rankB = this.rank.get(rb) ?? 0;
65:     let newRoot: string, child: string;
66:     if (rankA >= rankB) { newRoot = ra; child = rb; } else { newRoot = rb; child = ra; }
67:     this.parent.set(child, newRoot);
68:     if (rankA === rankB) this.rank.set(newRoot, rankA + 1);
69: 
70:     const newTiles = this.tiles.get(newRoot)!;
71:     for (const t of this.tiles.get(child)!) newTiles.add(t);
72:     this.tiles.delete(child);
73: 
74:     const newCounts = this.typeCounts.get(newRoot)!;
75:     for (const [t, n] of this.typeCounts.get(child)!) newCounts.set(t, (newCounts.get(t) ?? 0) + n);
76:     this.typeCounts.delete(child);
77: 
78:     const newSum = this.centroidSum.get(newRoot)!;
79:     const childSum = this.centroidSum.get(child)!;
80:     newSum.x += childSum.x;
81:     newSum.y += childSum.y;
82:     this.centroidSum.delete(child);
83: 
84:     this.tileCount.set(newRoot, (this.tileCount.get(newRoot) ?? 0) + (this.tileCount.get(child) ?? 0));
85:     this.tileCount.delete(child);
86: 
87:     this.rank.delete(child);
88:     return newRoot;
89:   }
90: 
91:   stats(root: string): ComponentStats {
92:     const r = this.find(root);
93:     const count = this.tileCount.get(r) ?? 0;
94:     const sum = this.centroidSum.get(r) ?? { x: 0, y: 0 };
95:     return {
96:       root: r,
97:       tileCount: count,
98:       typeCounts: new Map(this.typeCounts.get(r) ?? []),
99:       centroid: { x: sum.x / (count || 1), y: sum.y / (count || 1) },
100:     };
101:   }
102: 
103:   neighborsOf(tk: string): string[] {
104:     const [gx, gy] = parseTileKey(tk);
105:     const out: string[] = [];
106:     for (const [dx, dy] of NEIGHBORS_8) {
107:       const nk = tileKeyFor(gx + dx, gy + dy);
108:       if (this.parent.has(nk)) out.push(nk);
109:     }
110:     return out;
111:   }
112: 
113:   NEIGHBORS_8 = NEIGHBORS_8;
114: }

