      g.lineStyle(2, 0xffdc83, 0.95); g.lineBetween(shot.x, shot.y, shot.x - 6, shot.y - 6);
      g.fillStyle(0xffe6aa, 1); g.fillCircle(shot.x, shot.y, 3);
    }
    for (const threat of this.threats) {
