node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
const port = 9338;
const chrome = spawn('chromium', ['--headless=new', '--no-sandbox', '--disable-gpu', '--remote-allow-origins=*', `--remote-debugging-port=${port}`, '--user-data-dir=/tmp/opencode/rootbound-restart-check', 'about:blank'], { stdio: 'ignore' });
let socket;
try {
  const until = Date.now() + 15000;
  let version;
  while (Date.now() < until) {
    try { version = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json(); break; } catch { await new Promise(r => setTimeout(r, 100)); }
  }
  if (!version) throw new Error('Chrome DevTools did not start');
  const target = await (await fetch(`http://127.0.0.1:${port}/json/new?http://127.0.0.1:5173/`, { method: 'PUT' })).json();
  socket = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { socket.onopen = resolve; socket.onerror = reject; });
  let id = 0;
  const pending = new Map();
  socket.onmessage = event => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  };
  const cdp = (method, params = {}) => new Promise(resolve => {
    const callId = ++id;
    pending.set(callId, resolve);
    socket.send(JSON.stringify({ id: callId, method, params }));
  });
  await cdp('Runtime.enable');
  const evaluate = async expression => (await cdp('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })).result.result.value;
  let ready = false;
  for (let i = 0; i < 80; i++) {
    ready = await evaluate("!!document.querySelector('#game-ui canvas, canvas') && !!document.querySelector('[data-tile=\"glyph\"]')");
    if (ready) break;
    await new Promise(r => setTimeout(r, 100));
  }
  if (!ready) throw new Error('Game UI failed to load');
  await evaluate("document.querySelector('[data-tile=\"glyph\"]').click()");
  const before = await evaluate("({ name: document.querySelector('#selected-name').textContent, selected: document.querySelector('[data-tile=\"glyph\"]').classList.contains('selected') })");
  await evaluate("document.querySelector('#restart').click()");
  await new Promise(r => setTimeout(r, 700));
  const after = await evaluate("({ name: document.querySelector('#selected-name').textContent, selected: document.querySelector('[data-tile=\"stem\"]').classList.contains('selected'), tiles: document.querySelector('#tile-value').textContent, heart: document.querySelector('#core-value').textContent, endHidden: document.querySelector('#end-screen').hidden })");
  console.log(JSON.stringify({ before, after, restartVerified: before.name === 'Glyph' && before.selected && after.name === 'Stem' && after.selected && after.tiles === '1' && after.heart === '6 / 6' && after.endHidden }, null, 2));
  socket.close();
} finally {
  chrome.kill('SIGTERM');
}
